{
  "items": [
    {
      "name": "Polynomial.mapAlgHom_monomial",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u} {A : Type z} {B : Type u_2} [inst : CommSemiring R] [inst_1 : Semiring A] [inst_2 : Semiring B]\n  [inst_3 : Algebra R A] [inst_4 : Algebra R B] (f : A →ₐ[R] B) (n : ℕ) (a : A),\n  (Polynomial.mapAlgHom f) ((Polynomial.monomial n) a) = (Polynomial.monomial n) (f a)"
    },
    {
      "name": "MonoidAlgebra.mapRangeAlgHom_single",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_4} {B : Type u_5} {M : Type u_7} [inst : CommSemiring R] [inst_1 : Semiring A]\n  [inst_2 : Semiring B] [inst_3 : Algebra R A] [inst_4 : Algebra R B] [inst_5 : Monoid M] (f : A →ₐ[R] B) (m : M)\n  (a : A), (MonoidAlgebra.mapRangeAlgHom M f) (MonoidAlgebra.single m a) = MonoidAlgebra.single m (f a)"
    },
    {
      "name": "AddMonoidAlgebra.mapRangeAlgHom_single",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_4} {B : Type u_5} {M : Type u_7} [inst : CommSemiring R] [inst_1 : Semiring A]\n  [inst_2 : Semiring B] [inst_3 : Algebra R A] [inst_4 : Algebra R B] [inst_5 : AddMonoid M] (f : A →ₐ[R] B) (m : M)\n  (a : A), (AddMonoidAlgebra.mapRangeAlgHom M f) (AddMonoidAlgebra.single m a) = AddMonoidAlgebra.single m (f a)"
    },
    {
      "name": "Algebra.Generators.Hom.toAlgHom_monomial",
      "module_name": "Mathlib.RingTheory.Extension.Generators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} {ι : Type w} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  {P : Algebra.Generators R S ι} {R' : Type u_1} {S' : Type u_2} {ι' : Type u_3} [inst_3 : CommRing R']\n  [inst_4 : CommRing S'] [inst_5 : Algebra R' S'] {P' : Algebra.Generators R' S' ι'} [inst_6 : Algebra R R']\n  [inst_7 : Algebra S S'] (f : P.Hom P') (v : ι →₀ ℕ) (r : R),\n  f.toAlgHom ((MvPolynomial.monomial v) r) = r • v.prod fun x1 x2 => f.val x1 ^ x2"
    },
    {
      "name": "AddMonoidAlgebra.mapDomainAlgHom",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Basic",
      "kind": "definition",
      "type": "(R : Type u_1) →\n  (A : Type u_4) →\n    {M : Type u_7} →\n      {N : Type u_8} →\n        [inst : CommSemiring R] →\n          [inst_1 : Semiring A] →\n            [inst_2 : Algebra R A] →\n              [inst_3 : AddMonoid M] →\n                [inst_4 : AddMonoid N] → (M →+ N) → AddMonoidAlgebra A M →ₐ[R] AddMonoidAlgebra A N"
    }
  ]
}
